// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadSyncopate = makeLoadFont('Syncopate');
const loadInter = makeLoadFont('Inter');
const loadMontserrat = makeLoadFont('Montserrat');

// Load fonts at module level
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();
const { fontFamily: syncopateFamily } = loadSyncopate();
const { fontFamily: interFamily } = loadInter();
const { fontFamily: montserratFamily } = loadMontserrat();



export type MPDConstructionLogoProps = Record<string, any>;

const getFontFamily = (name: string) => {
  switch (name) {
    case "Montserrat": return montserratFamily;
    case "Space Grotesk": return spaceGroteskFamily;
    case "Syncopate": return syncopateFamily;
    case "Inter": return interFamily;
    default: return montserratFamily;
  }
};

const MPDConstructionLogo: React.FC<MPDConstructionLogoProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 6,
  primaryColor = "#1D1F38", // Deep Navy matching reference
  secondaryColor = "#F4911E", // Construction Orange matching reference
  gridLineColor = "#E5E7EB",
  blueprintGlowColor = "#3B82F6",
  mainText = "mpd",
  mainTextFontFamily = "Montserrat",
  mainTextScale = 1.0,
  mainTextLetterSpacing = -0.05,
  subText1 = "CONSTRUCTION",
  subText1FontFamily = "Montserrat",
  subText2 = "GROUP",
  subText2FontFamily = "Montserrat",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Resolve fonts
  const mainFont = getFontFamily(mainTextFontFamily);
  const sub1Font = getFontFamily(subText1FontFamily);
  const sub2Font = getFontFamily(subText2FontFamily);

  // Global Camera Animation
  const globalScale = interpolate(frame, [0, durationInSeconds * fps], [0.95, 1.05], {
    extrapolateRight: "clamp",
  });

  // Timings
  const blueprintDrawStart = 10;
  const blueprintDrawEnd = 60;
  const solidFadeStart = 45;
  const solidFadeEnd = 75;
  const sweepStart = 55;
  const sweepEnd = 105;
  const linesStart = 65;
  const subText1Start = 80;
  const subText1End = 110;
  const subText2Start = 105;

  // Animations - Blueprint phase
  const strokeDashoffset = interpolate(
    frame,
    [blueprintDrawStart, blueprintDrawEnd],
    [3000, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
  );
  
  const strokeOpacity = interpolate(
    frame,
    [solidFadeStart, solidFadeEnd],
    [0.8, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Animations - Solid formation
  const solidOpacity = interpolate(
    frame,
    [solidFadeStart, solidFadeEnd],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Metallic Light Sweep across the main text
  const sweepPosition = interpolate(
    frame,
    [sweepStart, sweepEnd],
    [-50, 150],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.ease) }
  );

  // Animations - Structural Lines
  const lineScale = spring({
    frame: frame - linesStart,
    fps,
    config: { damping: 14, stiffness: 80, mass: 0.8 },
  });

  // Animations - Text reveals
  const subText1Wipe = interpolate(
    frame,
    [subText1Start, subText1End],
    [100, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
  );

  const subText2Opacity = spring({
    frame: frame - subText2Start,
    fps,
    config: { damping: 20, stiffness: 100 },
  });
  
  const subText2Y = interpolate(
    frame,
    [subText2Start, subText2Start + 20],
    [10, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.quad) }
  );

  // Generate some random dust particles
  const particles = React.useMemo(() => {
    return new Array(30).fill(0).map((_, i) => ({
      id: i,
      x: random(`x-${i}`) * width,
      y: random(`y-${i}`) * height,
      size: random(`size-${i}`) * 3 + 1,
      speed: random(`speed-${i}`) * 0.5 + 0.1,
      opacity: random(`op-${i}`) * 0.3 + 0.1,
    }));
  }, [width, height]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Background Layer: Grid and Vignette */}
      {!transparentBackground && (
        <>
          <svg style={{ position: "absolute", width: "100%", height: "100%", opacity: 0.6 }}>
            <defs>
              <pattern id="archGrid" width="60" height="60" patternUnits="userSpaceOnUse">
                <path d="M 60 0 L 0 0 0 60" fill="none" stroke={gridLineColor} strokeWidth="1.5" />
                {/* Micro subdivision lines */}
                <path d="M 30 0 L 30 60 M 0 30 L 60 30" fill="none" stroke={gridLineColor} strokeWidth="0.5" opacity={0.5} />
              </pattern>
              <radialGradient id="vignette" cx="50%" cy="40%" r="70%">
                <stop offset="0%" stopColor="rgba(0,0,0,0)" />
                <stop offset="60%" stopColor="rgba(0,0,0,0)" />
                <stop offset="100%" stopColor="rgba(0,0,0,0.15)" />
              </radialGradient>
            </defs>
            <rect width="100%" height="100%" fill="url(#archGrid)" />
            <rect width="100%" height="100%" fill="url(#vignette)" />
          </svg>

          {/* Floating dust particles */}
          {particles.map((p) => (
            <div
              key={p.id}
              style={{
                position: "absolute",
                left: p.x,
                top: p.y - (frame * p.speed),
                width: p.size,
                height: p.size,
                backgroundColor: primaryColor,
                borderRadius: "50%",
                opacity: p.opacity * 0.4,
                filter: "blur(1px)",
                transform: `rotate(${frame * p.speed * 2}deg)`,
              }}
            />
          ))}
        </>
      )}

      {/* Main Content Wrapper - Cinematic Camera Push */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${globalScale})`,
          transformOrigin: "center center",
        }}
      >
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
          
          {/* TOP SECTION: 'mpd' Main Logo */}
          <div style={{ position: "relative", marginBottom: "8px", transform: `scale(${mainTextScale})` }}>
            {/* Invisible spacer to set dimensions based on standard text rendering */}
            <div
              style={{
                fontSize: "280px",
                fontFamily: mainFont,
                fontWeight: 900,
                letterSpacing: `${mainTextLetterSpacing}em`,
                lineHeight: 0.8,
                color: "transparent",
                userSelect: "none",
                padding: "20px",
              }}
            >
              {mainText}
            </div>

            {/* SVG Overlay for exact blueprint strokes and metallic fill */}
            <svg
              style={{
                position: "absolute",
                inset: 0,
                width: "100%",
                height: "100%",
                overflow: "visible",
              }}
            >
              <defs>
                <linearGradient id="metalSweep" x1={`${sweepPosition}%`} y1="0%" x2={`${sweepPosition + 30}%`} y2="100%">
                  <stop offset="0%" stopColor={primaryColor} />
                  <stop offset="40%" stopColor={primaryColor} />
                  {/* The metallic shine */}
                  <stop offset="50%" stopColor="#55587A" />
                  <stop offset="60%" stopColor={primaryColor} />
                  <stop offset="100%" stopColor={primaryColor} />
                </linearGradient>
                <filter id="glow">
                  <feGaussianBlur stdDeviation="4" result="coloredBlur"/>
                  <feMerge>
                    <feMergeNode in="coloredBlur"/>
                    <feMergeNode in="SourceGraphic"/>
                  </feMerge>
                </filter>
              </defs>

              {/* Solid Final Text */}
              <text
                x="50%"
                y="50%"
                dominantBaseline="middle"
                textAnchor="middle"
                style={{
                  fontSize: "280px",
                  fontFamily: mainFont,
                  fontWeight: 900,
                  letterSpacing: `${mainTextLetterSpacing}em`,
                  fill: "url(#metalSweep)",
                  opacity: solidOpacity,
                }}
              >
                {mainText}
              </text>

              {/* Blueprint Stroke Animation */}
              {strokeOpacity > 0 && (
                <text
                  x="50%"
                  y="50%"
                  dominantBaseline="middle"
                  textAnchor="middle"
                  style={{
                    fontSize: "280px",
                    fontFamily: mainFont,
                    fontWeight: 900,
                    letterSpacing: `${mainTextLetterSpacing}em`,
                    fill: "none",
                    stroke: blueprintGlowColor,
                    strokeWidth: 2,
                    strokeDasharray: 3000,
                    strokeDashoffset: strokeDashoffset,
                    opacity: strokeOpacity,
                    filter: "url(#glow)",
                  }}
                >
                  {mainText}
                </text>
              )}
            </svg>
          </div>

          {/* BOTTOM SECTION: Subtext & Lines */}
          {/* Using a flex container that hugs its contents to perfectly size the lines to the text width */}
          <div style={{ display: "flex", flexDirection: "column", alignItems: "stretch" }}>
            
            {/* Top Structural Line */}
            <div
              style={{
                width: "100%",
                height: "3px",
                backgroundColor: primaryColor,
                transform: `scaleX(${lineScale})`,
                transformOrigin: "left center",
              }}
            />

            {/* Subtext Row */}
            <div style={{ display: "flex", flexDirection: "row", padding: "6px 0", gap: "2px", alignItems: "center", justifyContent: "center" }}>
              
              {/* 'CONSTRUCTION' - CAD draw reveal */}
              <div
                style={{
                  fontFamily: sub1Font,
                  fontWeight: 900,
                  fontSize: "36px",
                  color: secondaryColor,
                  letterSpacing: "0.02em",
                  clipPath: `inset(0 ${subText1Wipe}% 0 0)`,
                  lineHeight: 1,
                }}
              >
                {subText1}
              </div>

              {/* 'GROUP' - Subtle fade up */}
              <div
                style={{
                  fontFamily: sub2Font,
                  fontWeight: 400,
                  fontSize: "36px",
                  color: primaryColor,
                  letterSpacing: "0.02em",
                  opacity: subText2Opacity,
                  transform: `translateY(${subText2Y}px)`,
                  lineHeight: 1,
                }}
              >
                {subText2}
              </div>
            </div>

            {/* Bottom Structural Line */}
            <div
              style={{
                width: "100%",
                height: "3px",
                backgroundColor: primaryColor,
                transform: `scaleX(${lineScale})`,
                transformOrigin: "right center",
              }}
            />
          </div>

        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default MPDConstructionLogo;